// =====================================================================
//  KONFIGURACJA – to jedyne miejsce, które instalator musi edytować.
//  Po zmianie: kliknij "Done", a potem "Deploy".
// =====================================================================
const config = {
    // ID zamka w chmurze TTLock (odczytasz go skryptem tools/ttlock_test.py).
    // Puste '' = TRYB NAUKI: zdarzenia z chmury są tylko logowane (z lockId i lockMac
    // do skopiowania), NIE uruchamiają KNX. Przyciski TEST działają zawsze.
    lockId: '',

    // Adres MAC czytnika (drugie zabezpieczenie – callback TTLock nie ma podpisu).
    // Odczytasz go skryptem tools/ttlock_test.py albo z logu w trybie nauki.
    // Puste '' = bez sprawdzania MAC. Format dowolny, np. 'C5:40:E0:9C:8C:C1'.
    lockMac: '',

    // Rekord starszy niż tyle minut nie uruchomi automatyki
    // (np. bramka była offline i wysłała zaległe zdarzenia). Zakres 1–1440.
    maksWiekMinut: 5,

    // Typy otwarcia, które uruchamiają automatykę:
    //  8 = odcisk palca, 4 = kod PIN, 7 = karta/brelok RFID, 55 = pilot
    //  1 = aplikacja (eKey), 12 = zdalnie przez bramkę – dodaj dopiero po teście
    // Dozwolone także: 9 opaska, 49 karta hotelowa, 57 kod QR, 67 twarz,
    //  75/76 otwarcie przez udzielenie z aplikacji/zdalnie, 84/85 żyły dłoni, 92 kod administratora.
    // NIE dodawaj 77–83: to podwójna autoryzacja – pierwsza osoba zweryfikowana,
    //  drzwi nadal ZAMKNIĘTE (czekają na drugą osobę). Konfiguracja je odrzuci.
    typyPrzyjscia: [8, 4, 7, 55],

    // 10 miejsc na osoby. Numer miejsca = adres wyzwalacza KNX 7/3/<nr>.
    //   klucz: PIERWSZE SŁOWO nazwy odcisku/karty/kodu w aplikacji,
    //          małymi literami, bez polskich znaków ("Łukasz - kciuk" -> 'lukasz').
    //          Puste '' = miejsce wolne.
    //   nazwa: tekst na KNX "Ostatnio otworzył" (max 14 znaków)
    //   scena: numer sceny KNX 1–64 wysyłany na 7/1/0 (jak w ETS), 0 = bez sceny
    osoby: [
        /*  1 → 7/3/1  */ { klucz: 'anna',   nazwa: 'Anna',   scena: 1 },
        /*  2 → 7/3/2  */ { klucz: 'piotr',  nazwa: 'Piotr',  scena: 2 },
        /*  3 → 7/3/3  */ { klucz: 'lukasz', nazwa: 'Lukasz', scena: 3 },
        /*  4 → 7/3/4  */ { klucz: '',       nazwa: 'Osoba 4',  scena: 4 },
        /*  5 → 7/3/5  */ { klucz: '',       nazwa: 'Osoba 5',  scena: 5 },
        /*  6 → 7/3/6  */ { klucz: '',       nazwa: 'Osoba 6',  scena: 6 },
        /*  7 → 7/3/7  */ { klucz: '',       nazwa: 'Osoba 7',  scena: 7 },
        /*  8 → 7/3/8  */ { klucz: '',       nazwa: 'Osoba 8',  scena: 8 },
        /*  9 → 7/3/9  */ { klucz: '',       nazwa: 'Osoba 9',  scena: 9 },
        /* 10 → 7/3/10 */ { klucz: '',       nazwa: 'Osoba 10', scena: 10 },
    ],
};

// =====================================================================
//  Poniżej nic nie zmieniaj – sprawdzenie poprawności konfiguracji.
// =====================================================================
function bezOgonkow(t) {
    return String(t).replace(/ł/g, 'l').replace(/Ł/g, 'L')
        .normalize('NFD').replace(/[̀-ͯ]/g, '');
}
function tekstKnx(t) {
    // DPT 16.001 = ISO 8859-1, maks. 14 znaków
    return bezOgonkow(t).replace(/[^\x20-\x7E\xA0-\xFF]/g, '').trim().substring(0, 14);
}

const bledy = [];
const lockId = String(config.lockId === undefined || config.lockId === null ? '' : config.lockId).trim();
if (lockId && !/^\d+$/.test(lockId)) bledy.push('lockId może zawierać tylko cyfry');

// Sprawdzamy surowy tekst PRZED normalizacją – inaczej np. 'XYZ' dałoby pusty MAC
// i po cichu wyłączyło kontrolę.
const lockMacSurowy = String(config.lockMac === undefined || config.lockMac === null ? '' : config.lockMac).trim();
if (lockMacSurowy && !/^([0-9A-Fa-f]{2}[:-]?){5}[0-9A-Fa-f]{2}$/.test(lockMacSurowy)) {
    bledy.push('lockMac nie wygląda jak adres MAC, np. C5:40:E0:9C:8C:C1 (albo zostaw puste)');
}
const lockMac = lockMacSurowy.toUpperCase().replace(/[^0-9A-F]/g, '');

const maksWiekMinut = Number(config.maksWiekMinut);
if (!(Number.isFinite(maksWiekMinut) && maksWiekMinut >= 1 && maksWiekMinut <= 1440)) {
    bledy.push('maksWiekMinut musi być liczbą 1–1440');
}

const typyPrzyjscia = Array.isArray(config.typyPrzyjscia) ? config.typyPrzyjscia.map(Number) : [];
if (!typyPrzyjscia.length || typyPrzyjscia.some(t => !Number.isInteger(t) || t <= 0)) {
    bledy.push('typyPrzyjscia musi być listą numerów, np. [8, 4, 7, 55]');
}
// Tylko udane otwarcia z możliwą identyfikacją osoby. Bez: klucza mechanicznego (10),
// siły (29), otwarcia od środka (32), alarmów, nieudanych prób i podwójnej autoryzacji 77–83.
const DOZWOLONE_TYPY = [1, 4, 7, 8, 9, 12, 49, 55, 57, 67, 75, 76, 84, 85, 92];
const niedozwolone = typyPrzyjscia.filter(t => !DOZWOLONE_TYPY.includes(t));
if (niedozwolone.length) {
    bledy.push(`typyPrzyjscia: niedozwolone typy ${niedozwolone.join(', ')} – dozwolone: ${DOZWOLONE_TYPY.join(', ')}`);
}

const listaOsob = Array.isArray(config.osoby) ? config.osoby : [];
if (listaOsob.length > 10) bledy.push('maksymalnie 10 osób (flow ma 10 wyzwalaczy KNX)');
const osoby = listaOsob.slice(0, 10).map((o, i) => {
    o = o || {};
    const klucz = bezOgonkow(String(o.klucz || '').trim()).toLowerCase();
    const scena = Number(o.scena === undefined || o.scena === null || o.scena === '' ? 0 : o.scena);
    if (klucz && !/^[a-z0-9]+$/.test(klucz)) bledy.push(`osoba ${i + 1}: klucz może zawierać tylko litery i cyfry (jedno słowo)`);
    if (!Number.isInteger(scena) || scena < 0 || scena > 64) bledy.push(`osoba ${i + 1}: scena musi być liczbą 0–64`);
    const nazwa = tekstKnx(o.nazwa || klucz || `Osoba ${i + 1}`) || `Osoba ${i + 1}`;
    return { klucz, nazwa, scena };
});
const klucze = osoby.map(o => o.klucz).filter(Boolean);
klucze.filter((k, i) => klucze.indexOf(k) !== i)
    .forEach(k => bledy.push(`klucz "${k}" występuje dwa razy`));

if (bledy.length) {
    // Błędna konfiguracja NIE zastępuje ostatniej poprawnej.
    const stara = flow.get('config');
    node.error('Błędna KONFIGURACJA – popraw i kliknij Deploy: ' + bledy.join('; '));
    node.status({ fill: 'red', shape: 'ring',
        text: `BŁĄD: ${bledy[0]}` + (stara ? ' (działa poprzednia konfiguracja)' : '') });
    return null;
}

flow.set('config', { lockId, lockMac, maksWiekMinut, typyPrzyjscia, osoby });
node.status({ fill: lockId ? 'green' : 'yellow', shape: 'dot',
    text: `${klucze.length}/10 osób` + (lockId ? `, zamek ${lockId}` + (lockMac ? ' + MAC' : '') : ', TRYB NAUKI (brak lockId)') });
return null;

// Odbiera callback TTLock "Lock Records Notify", filtruje i mapuje osobę na automatykę.
// Wyjścia: 1 = odpowiedź HTTP "success", 2 = scena KNX, 3 = tekst KNX,
//          4 = wyzwalacz osoby (msg.miejsce 1–10), 5 = log
// Wszystkie 61 typów z dokumentacji TTLock "Record type of cloud" (tylko do opisu w logu).
const TYPY = {
    1: 'aplikacja (eKey)', 4: 'kod PIN', 5: 'podniesienie (parking)', 6: 'opuszczenie (parking)',
    7: 'karta/brelok RFID', 8: 'odcisk palca', 9: 'opaska', 10: 'klucz mechaniczny',
    11: 'zamknięcie z aplikacji', 12: 'zdalnie przez bramkę', 29: 'otwarcie siłowe',
    30: 'czujnik drzwi: zamknięte', 31: 'czujnik drzwi: otwarte', 32: 'otwarcie od środka',
    33: 'zamknięcie odciskiem', 34: 'zamknięcie kodem', 35: 'zamknięcie kartą', 36: 'zamknięcie kluczem',
    37: 'sterowanie przyciskiem w aplikacji', 42: 'nowa poczta lokalna', 43: 'nowa poczta z innego miasta',
    44: 'sabotaż', 45: 'autozamykanie', 46: 'przycisk otwierania', 47: 'przycisk zamykania',
    48: 'blokada po błędnych próbach', 49: 'karta hotelowa', 50: 'otwarcie z powodu wysokiej temperatury',
    51: 'próba usuniętą kartą', 52: 'blokada (dead lock) z aplikacji', 53: 'blokada (dead lock) kodem',
    54: 'samochód wyjechał (parking)', 55: 'pilot', 57: 'kod QR', 58: 'kod QR wygasły – nieudane',
    59: 'podwójne zamknięcie', 60: 'anulowanie podwójnego zamknięcia', 61: 'zamknięcie kodem QR',
    62: 'kod QR – zamek podwójnie zamknięty', 63: 'autootwarcie (tryb przejścia)',
    64: 'alarm: drzwi niezamknięte', 65: 'nieudane otwarcie', 66: 'nieudane zamknięcie', 67: 'twarz',
    68: 'twarz – zamknięte od środka', 69: 'zamknięcie twarzą', 71: 'twarz – nieważna',
    75: 'udzielenie z aplikacji', 76: 'udzielenie zdalne',
    77: 'podwójna autoryzacja: Bluetooth – czeka na 2. osobę', 78: 'podwójna autoryzacja: kod – czeka na 2. osobę',
    79: 'podwójna autoryzacja: odcisk – czeka na 2. osobę', 80: 'podwójna autoryzacja: karta – czeka na 2. osobę',
    81: 'podwójna autoryzacja: twarz – czeka na 2. osobę', 82: 'podwójna autoryzacja: pilot – czeka na 2. osobę',
    83: 'podwójna autoryzacja: żyły dłoni – czeka na 2. osobę',
    84: 'żyły dłoni', 85: 'żyły dłoni', 86: 'zamknięcie żyłami dłoni', 88: 'żyły dłoni – nieważne',
    92: 'kod administratora',
};
// W tych rekordach keyboardPwd może zawierać prawdziwy PIN – zawsze maskowany w logu.
const TYPY_PIN = [4, 34, 53, 78, 92];
const MAKS_REKORDOW = 50;       // ochrona przed zalaniem dużym zapytaniem
const PAMIEC_DUPLIKATOW = 500;  // ile ostatnich rekordów pamiętać
const ZEGAR_TOLERANCJA_MS = 5 * 60000;     // do 5 min w przyszłości: bez uwag
const PRZYSZLOSC_MAKS_MS = 60 * 60000;     // ponad 1 h w przyszłości: rekord niewiarygodny

function bezOgonkow(t) {
    return String(t).replace(/ł/g, 'l').replace(/Ł/g, 'L')
        .normalize('NFD').replace(/[̀-ͯ]/g, '');
}
function tekstKnx(t) {
    return bezOgonkow(t).replace(/[^\x20-\x7E\xA0-\xFF]/g, '').trim().substring(0, 14);
}
function klucz(nazwa) {
    return bezOgonkow(String(nazwa).trim().split(/[\s\-_–—.,;:/]+/)[0] || '').toLowerCase();
}
function maskuj(r) {
    const kopia = Object.assign({}, r);
    if (TYPY_PIN.includes(Number(r.recordType)) && kopia.keyboardPwd) kopia.keyboardPwd = '****';
    return kopia;
}
function normalizujMac(m) {
    return String(m === undefined || m === null ? '' : m).toUpperCase().replace(/[^0-9A-F]/g, '');
}
function czytajRekordy(pole) {
    let v = pole;
    if (typeof v === 'string') v = JSON.parse(v);
    if (v && !Array.isArray(v) && typeof v === 'object') v = [v];
    return Array.isArray(v) ? v.filter(r => r && typeof r === 'object') : [];
}

// TTLock oczekuje odpowiedzi "success" – odpowiadamy ZAWSZE, także przy błędach,
// żeby chmura nie ponawiała wysyłki. Testy z przycisków nie mają msg.res.
const odpowiedz = msg.res ? { req: msg.req, res: msg.res, statusCode: 200,
    headers: { 'Content-Type': 'text/plain; charset=utf-8' }, payload: 'success' } : null;

function przetworz() {
    const cfg = flow.get('config');
    if (!cfg) {
        node.warn('Brak poprawnej konfiguracji – popraw węzeł ⚙ KONFIGURACJA i kliknij Deploy.');
        return [odpowiedz, null, null, null, { payload: 'Brak konfiguracji – zdarzenie pominięte' }];
    }

    const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
    const lockId = String(body.lockId === undefined ? '' : body.lockId).trim();
    if (cfg.lockId && lockId !== cfg.lockId) {
        return [odpowiedz, null, null, null, { payload: `Obcy lockId "${lockId}" – zignorowano` }];
    }
    if (cfg.lockMac && normalizujMac(body.lockMac) !== cfg.lockMac) {
        return [odpowiedz, null, null, null, { payload: `Niezgodny lockMac "${body.lockMac || '(brak)'}" – zignorowano` }];
    }
    if (body.notifyType !== undefined && String(body.notifyType) !== '1') {
        return [odpowiedz, null, null, null, { payload: `notifyType=${body.notifyType} (to nie rekord otwarcia) – pominięto` }];
    }

    let rekordy;
    try {
        rekordy = czytajRekordy(body.records);
    } catch (e) {
        return [odpowiedz, null, null, null, { payload: 'Nieczytelne pole "records" – pominięto: ' + e.message }];
    }
    const logi = [];
    if (rekordy.length > MAKS_REKORDOW) {
        logi.push({ payload: `Za dużo rekordów (${rekordy.length}) – przetwarzam ostatnie ${MAKS_REKORDOW}` });
        rekordy = rekordy.slice(-MAKS_REKORDOW);
    }

    const wlaczona = flow.get('automatykaWlaczona') !== false;
    const widziane = flow.get('widziane') || [];
    const teraz = Date.now();
    const sceny = [], teksty = [], wyzwalacze = [];
    // Tryb nauki: bez lockId zdarzenia z chmury tylko logujemy (przyciski TEST nie mają msg.res).
    const trybNauki = !cfg.lockId && !!msg.res;
    const uwagaLock = cfg.lockId ? ''
        : (msg.res ? ` | TRYB NAUKI: wpisz lockId '${lockId}' i lockMac '${body.lockMac || ''}' w KONFIGURACJI`
            : ' | TEST (lockId nieustawiony – zdarzenia z chmury tylko w logu)');

    for (const r of rekordy) {
        const typ = Number(r.recordType);
        const nazwa = String(r.username === undefined || r.username === null ? '' : r.username);
        const czasZamka = Number(r.lockDate);
        // Wiek liczony od czasu serwera TTLock – zegar czytnika może się rozjechać
        // (np. po zaniku zasilania), zegar serwera jest pewny.
        const czasSerwera = Number(r.serverDate) > 0 ? Number(r.serverDate) : czasZamka;
        const id = `${lockId}|${r.lockDate}|${typ}|${nazwa}`;
        const osobaKlucz = klucz(nazwa);
        const miejsce = osobaKlucz ? cfg.osoby.findIndex(o => o.klucz === osobaKlucz) + 1 : 0;
        const osoba = miejsce ? cfg.osoby[miejsce - 1] : null;
        const wiek = teraz - czasSerwera;
        let decyzja;

        if (!Number.isFinite(czasSerwera) || czasSerwera <= 0) decyzja = 'brak czasu w rekordzie – pominięto';
        else if (widziane.includes(id)) decyzja = 'duplikat – pominięto';
        else if (Number(r.success) !== 1) decyzja = 'nieudana próba – pominięto';
        else if (!cfg.typyPrzyjscia.includes(typ)) decyzja = 'ten typ nie uruchamia automatyki';
        else if (wiek > cfg.maksWiekMinut * 60000) decyzja = 'rekord zbyt stary – pominięto';
        else if (wiek < -PRZYSZLOSC_MAKS_MS) decyzja = 'czas rekordu ponad 1 h w przyszłości – niewiarygodny, pominięto';
        else if (!osoba) decyzja = `nieznana osoba "${osobaKlucz}" – dodaj ją w KONFIGURACJI`;
        else if (!wlaczona) decyzja = 'automatyka wyłączona z KNX – pominięto';
        else if (trybNauki) decyzja = `rozpoznano OSOBĘ ${miejsce}, ale TRYB NAUKI – KNX nie wysłany`;
        else {
            decyzja = `OSOBA ${miejsce} (7/3/${miejsce})` + (osoba.scena ? `, SCENA ${osoba.scena}` : '');
            if (osoba.scena) sceny.push({ payload: { save_recall: 0, scenenumber: osoba.scena }, osoba: osoba.nazwa });
            wyzwalacze.push({ payload: true, miejsce, osoba: osoba.nazwa });
            teksty.push({ payload: tekstKnx(osoba.nazwa) });
        }
        if (Number.isFinite(czasSerwera) && czasSerwera > 0) widziane.push(id);
        if (wiek < -ZEGAR_TOLERANCJA_MS && wiek >= -PRZYSZLOSC_MAKS_MS) decyzja += ' | UWAGA: zegar komputera spóźnia się – sprawdź NTP';
        // recordTypeFromLock = co fizycznie zrobił zamek (może różnić się od typu z chmury) – do diagnostyki
        const zZamka = r.recordTypeFromLock !== undefined && r.recordTypeFromLock !== null ? ` (zamek: ${r.recordTypeFromLock})` : '';

        const czas = Number.isFinite(czasZamka) && czasZamka > 0
            ? new Date(czasZamka).toLocaleString('pl-PL') : '(brak czasu)';
        const opoznienie = Number.isFinite(wiek) ? `${(wiek / 1000).toFixed(1)} s` : '?';
        logi.push({
            payload: `${czas} | ${TYPY[typ] || 'typ ' + typ}${zZamka} | "${nazwa}" | ${decyzja} | opóźnienie ${opoznienie}${uwagaLock}`,
            rekord: maskuj(r),
        });
    }
    flow.set('widziane', widziane.slice(-PAMIEC_DUPLIKATOW));
    if (rekordy.length) flow.set('ostatniCallback', teraz);

    const ostatni = logi.length ? logi[logi.length - 1].payload.split(' | ') : null;
    if (ostatni && ostatni.length > 3) {
        node.status({ fill: wyzwalacze.length ? 'green' : 'grey', shape: 'dot',
            text: `${ostatni[2]}: ${ostatni[3]}`.substring(0, 60) });
    }
    return [odpowiedz, sceny, teksty, wyzwalacze, logi];
}

try {
    return przetworz();
} catch (e) {
    node.error('Błąd przetwarzania callbacku: ' + e.message);
    node.status({ fill: 'red', shape: 'ring', text: 'błąd: ' + String(e.message).substring(0, 50) });
    return [odpowiedz, null, null, null, { payload: 'BŁĄD przetwarzania: ' + e.message }];
}

// Zapamiętuje stan GA "automatyka włączona" (DPT 1.001) odebrany z KNX.
const v = msg.payload;
const wl = v === true || v === 1 || v === '1' || v === 'true';
flow.set('automatykaWlaczona', wl);
node.status({ fill: wl ? 'green' : 'red', shape: 'dot', text: wl ? 'automatyka WŁ' : 'automatyka WYŁ' });
return null;

// Symuluje callback z chmury TTLock – do testów bez zamka.
const cfg = flow.get('config') || {};
const lockId = cfg.lockId || '1234567';
const teraz = Date.now();
const scenariusze = {
    palec:    { recordType: 8,  username: 'Anna - kciuk',  keyboardPwd: '44668054142981' },
    pin:      { recordType: 4,  username: 'Piotr kod',     keyboardPwd: '123456' },
    srodek:   { recordType: 32, username: '',              keyboardPwd: '' },
    nieznany: { recordType: 7,  username: 'Gosc brelok',   keyboardPwd: '0012345678' },
};
const s = scenariusze[msg.topic] || scenariusze.palec;
msg.payload = {
    lockId: String(lockId),
    notifyType: '1',
    lockMac: cfg.lockMac || 'AABBCCDDEEFF',
    records: JSON.stringify([Object.assign({
        lockId: Number(lockId), success: 1, lockDate: teraz - 2000,
        serverDate: teraz - 500, electricQuantity: 100,
    }, s)]),
};
return msg;

// SERWIS – uruchamiany przy starcie i co 6 godzin.
//  1. Loguje się do TTLock kontem administratora zamka. Odświeża to token dla
//     naszego clientId, dzięki czemu callbacki nie przestają przychodzić
//     (TTLock wysyła je do aplikacji z najdłużej ważnym tokenem administratora).
//  2. Sprawdza, czy bramka widzi czytnik (gateway/listByLock, ostatnie 30 min).
//  3. Porównuje zegar komputera z zegarem serwera TTLock.
// Wyjścia: 1 = KNX "Integracja OK" (DPT 1.001), 2 = log
// Dane logowania: zmienne zakładki (typ "credential") – patrz instrukcja, krok 10a.
const API = 'https://euapi.ttlock.com';
const PROG_AWARII = 2;            // ile kolejnych nieudanych kontroli, zanim wyślemy 0 na KNX
const ZEGAR_TOLERANCJA_S = 120;

const clientId = env.get('TTLOCK_CLIENT_ID');
const clientSecret = env.get('TTLOCK_CLIENT_SECRET');
const uzytkownik = env.get('TTLOCK_USER');
const haslo = env.get('TTLOCK_PASS');

if (!clientId || !clientSecret || !uzytkownik || !haslo) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'wyłączony – brak danych TTLock (krok 10a)' });
    return null;
}

function zapytanie(metoda, sciezka, parametry) {
    return new Promise((ok, blad) => {
        const dane = new URLSearchParams(parametry).toString();
        const url = API + sciezka + (metoda === 'GET' ? '?' + dane : '');
        const naglowki = metoda === 'GET' ? {} : {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Content-Length': Buffer.byteLength(dane),
        };
        const req = https.request(url, { method: metoda, timeout: 20000, headers: naglowki }, res => {
            let tekst = '';
            res.setEncoding('utf8');
            res.on('data', c => { tekst += c; if (tekst.length > 1e6) req.destroy(new Error('odpowiedź za duża')); });
            res.on('end', () => {
                let json = null;
                try { json = JSON.parse(tekst); } catch (e) { /* obsłużone niżej */ }
                if (!json || typeof json !== 'object') return blad(new Error(`nieczytelna odpowiedź HTTP ${res.statusCode}`));
                ok({ status: res.statusCode, data: res.headers.date, json });
            });
        });
        req.on('timeout', () => req.destroy(new Error('brak odpowiedzi serwera TTLock (timeout)')));
        req.on('error', blad);
        req.end(metoda === 'GET' ? undefined : dane);
    });
}

const cfg = flow.get('config');
const krytyczne = [], ostrzezenia = [], info = [];

try {
    const t = await zapytanie('POST', '/oauth2/token', {
        clientId, clientSecret, username: uzytkownik,
        password: crypto.createHash('md5').update(String(haslo)).digest('hex'),
    });
    if (t.data) {
        const roznica = Math.round((Date.now() - Date.parse(t.data)) / 1000);
        if (Math.abs(roznica) > ZEGAR_TOLERANCJA_S) ostrzezenia.push(`zegar komputera różni się o ${roznica} s – sprawdź NTP`);
    }
    if (!t.json.access_token) {
        krytyczne.push(`logowanie TTLock nieudane: ${t.json.errcode} ${t.json.errmsg || ''} – sprawdź clientId, clientSecret i hasło administratora`);
    } else {
        info.push(`token ważny ${Math.round((t.json.expires_in || 0) / 86400)} dni`);
        if (!cfg || !cfg.lockId) {
            ostrzezenia.push('lockId nieustawiony – pominięto kontrolę bramki');
        } else {
            const g = await zapytanie('GET', '/v3/gateway/listByLock', {
                clientId, accessToken: t.json.access_token, lockId: cfg.lockId, date: Date.now(),
            });
            if (g.json.errcode) {
                krytyczne.push(`kontrola bramki: ${g.json.errcode} ${g.json.errmsg || ''}`);
            } else {
                const lista = Array.isArray(g.json.list) ? g.json.list : [];
                if (!lista.length) {
                    krytyczne.push('żadna bramka nie widzi czytnika (bramka offline, bez zasilania lub poza zasięgiem)');
                } else {
                    const rssi = Math.max(...lista.map(b => Number(b.rssi)).filter(Number.isFinite), -999);
                    info.push(`bramka ${rssi > -999 ? rssi + ' dBm' : 'OK'}`);
                    if (rssi > -999 && rssi < -85) ostrzezenia.push(`słaby sygnał bramki (${rssi} dBm) – przybliż bramkę do czytnika`);
                }
            }
        }
    }
} catch (e) {
    krytyczne.push('brak połączenia z TTLock: ' + e.message);
}

const ostatni = flow.get('ostatniCallback');
if (ostatni) info.push(`ostatnie zdarzenie ${Math.round((Date.now() - ostatni) / 3600000)} h temu`);

const awarie = krytyczne.length ? (context.get('awarie') || 0) + 1 : 0;
context.set('awarie', awarie);
const ok = awarie < PROG_AWARII;   // pojedyncza przerwa internetu nie alarmuje

const opis = [...krytyczne, ...ostrzezenia, ...info].join(' | ');
node.status({ fill: krytyczne.length ? 'red' : (ostrzezenia.length ? 'yellow' : 'green'), shape: 'dot',
    text: (krytyczne.length ? `BŁĄD (${awarie}x): ` : 'OK: ') + opis.substring(0, 70) });
if (krytyczne.length) node.warn('SERWIS: ' + opis);

return [{ payload: ok }, { payload: `SERWIS ${krytyczne.length ? 'BŁĄD' : 'OK'} | ${opis}` }];
